window.ScripturaLexicons.BDAG_PART_0129 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exerama-bdag\" data-source=\"BDAG\" data-search=\"ἐξέραμα, ατος, τό exérama substantivo neutro vômito; aquilo que foi vomitado BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξέραμα, ατος, τό</td><td>substantivo neutro</td><td>vômito; aquilo que foi vomitado</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exeraunao-bdag\" data-source=\"BDAG\" data-search=\"ἐξεραυνάω exeraunáō verbo investigar cuidadosamente; procurar descobrir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξεραυνάω</td><td>verbo</td><td>investigar cuidadosamente; procurar descobrir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exereunao-bdag\" data-source=\"BDAG\" data-search=\"ἐξερευνάω exereunáō verbo; remissão ver ἐξεραυνάω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξερευνάω</td><td>verbo; remissão</td><td>ver ἐξεραυνάω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exerizo-bdag\" data-source=\"BDAG\" data-search=\"ἐξερίζω exerízō verbo ser faccioso; ser contencioso BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξερίζω</td><td>verbo</td><td>ser faccioso; ser contencioso</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exerchomai-bdag\" data-source=\"BDAG\" data-search=\"ἐξέρχομαι exérchomai verbo sair; ir embora; proceder; morrer; escapar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξέρχομαι</td><td>verbo</td><td>sair; ir embora; proceder; morrer; escapar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exestakenai-bdag\" data-source=\"BDAG\" data-search=\"ἐξεστακέναι exestakénai forma verbal; remissão ver ἐξίστημι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξεστακέναι</td><td>forma verbal; remissão</td><td>ver ἐξίστημι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exestin-bdag\" data-source=\"BDAG\" data-search=\"ἔξεστιν éxestin verbo impessoal ser permitido; ser apropriado; ser possível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἔξεστιν</td><td>verbo impessoal</td><td>ser permitido; ser apropriado; ser possível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exetazo-bdag\" data-source=\"BDAG\" data-search=\"ἐξετάζω exetázō verbo examinar; investigar; interrogar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξετάζω</td><td>verbo</td><td>examinar; investigar; interrogar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exetasmos-bdag\" data-source=\"BDAG\" data-search=\"ἐξετασμός, οῦ, ὁ exetasmós substantivo masculino investigação; exame; inquérito BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξετασμός, οῦ, ὁ</td><td>substantivo masculino</td><td>investigação; exame; inquérito</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exetastikos-bdag\" data-source=\"BDAG\" data-search=\"ἐξεταστικῶς exetastikôs advérbio mediante investigação minuciosa BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξεταστικῶς</td><td>advérbio</td><td>mediante investigação minuciosa</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exephnes-bdag\" data-source=\"BDAG\" data-search=\"ἐξέφνης exéphnēs advérbio; remissão ver ἐξαίφνης BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξέφνης</td><td>advérbio; remissão</td><td>ver ἐξαίφνης</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exechythen-bdag\" data-source=\"BDAG\" data-search=\"ἐξεχύθην exechýthēn forma verbal; remissão ver ἐκχέω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξεχύθην</td><td>forma verbal; remissão</td><td>ver ἐκχέω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-execho-bdag\" data-source=\"BDAG\" data-search=\"ἐξέχω exéchō verbo sobressair; destacar-se; ser proeminente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξέχω</td><td>verbo</td><td>sobressair; destacar-se; ser proeminente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exegeomai-bdag\" data-source=\"BDAG\" data-search=\"ἐξηγέομαι exēgéomai verbo médio depoente relatar detalhadamente; explicar; expor BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξηγέομαι</td><td>verbo médio depoente</td><td>relatar detalhadamente; explicar; expor</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exegesis-bdag\" data-source=\"BDAG\" data-search=\"ἐξήγησις, εως, ἡ exḗgēsis substantivo feminino narração; descrição; explicação; interpretação BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξήγησις, εως, ἡ</td><td>substantivo feminino</td><td>narração; descrição; explicação; interpretação</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exiein-exeesan-bdag\" data-source=\"BDAG\" data-search=\"ἐξῄειν, ἐξήεσαν exḗiein, exḗesan formas verbais; remissão imperfeito de ἔξειμι BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξῄειν, ἐξήεσαν</td><td>formas verbais; remissão</td><td>imperfeito de ἔξειμι</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hexekonta-bdag\" data-source=\"BDAG\" data-search=\"ἑξήκοντα hexḗkonta numeral indeclinável sessenta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑξήκοντα</td><td>numeral indeclinável</td><td>sessenta</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-hexes-bdag\" data-source=\"BDAG\" data-search=\"ἑξῆς hexês advérbio seguinte; depois; no dia seguinte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἑξῆς</td><td>advérbio</td><td>seguinte; depois; no dia seguinte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-execheo-bdag\" data-source=\"BDAG\" data-search=\"ἐξηχέω exēchéō verbo ressoar; repercutir; fazer ouvir BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξηχέω</td><td>verbo</td><td>ressoar; repercutir; fazer ouvir</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-exiemi-bdag\" data-source=\"BDAG\" data-search=\"ἐξίημι exíēmi verbo deixar sair; enviar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">ἐξίημι</td><td>verbo</td><td>deixar sair; enviar</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article id=\"entry-exerama-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξέραμα, ατος, τό</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exérama⟧</span><span class=\"separator\">·</span><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξέραμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (<span class=\"greek\">ἔραμα</span> em Diosc., De Venen. 19): aquilo que foi vomitado, vômito, de um cão (Philumen., p. 8, 30), 2Pe 2:22. — DELG, s.v. <span class=\"greek\">ἐξεράω</span>; Frisk, s.v. <span class=\"greek\">ἀπεράω</span>; cf. <span class=\"greek\">ἔρα</span>, «terra». M-M.</p></section></article>\n<article id=\"entry-exeraunao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξεραυνάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exeraunáō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξεραυνάω</span>: futuro <span class=\"greek\">ἐξερευνήσω</span> na LXX; primeiro aoristo <span class=\"greek\">ἐξηραύνησα</span>; aoristo passivo, terceira pessoa do singular <span class=\"greek\">ἐξηρευνήθη</span>, na LXX (substituto no grego helenístico de <span class=\"greek\">ἐξερευνάω</span> [variante nas edições], forma encontrada em Soph. e outros. Sobre a mudança fonética, ver <span class=\"greek\">ἐραυνάω</span>. A forma composta ocorre também em Polyb.; Plut.; Vett. Val. 267, 5; LXX; PsSol 17, 9; Philo, Plant. 141; Jos., Bell. 4, 654; Mel., P. 23, 160). Fazer uma investigação cuidadosa, procurar descobrir; <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «acerca de alguma coisa», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Pe 1:10</a>. — DELG, s.v. <span class=\"greek\">ἐρέω</span>. M-M. TW.</p></section></article>\n<article id=\"entry-exereunao-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξερευνάω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exereunáō⟧</span><span class=\"separator\">·</span><span>verbo; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξερευνάω</span>: ver <span class=\"greek\">ἐξεραυνάω</span>.</p></section></article>\n<article id=\"entry-exerizo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξερίζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exerízō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξερίζω</span>: primeiro aoristo <span class=\"greek\">ἐξήρισα</span> (ver <span class=\"greek\">ἐρίζω</span>, <span class=\"greek\">ἔρις</span>; Plut., Pomp. 649 [56, 3]; Appian, Bell. Civ. 2, 151 §634). Ser faccioso, contencioso; <span class=\"greek\">ἐξήρισαν</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοσοῦτο</span> <span class=\"greek\">θυμοῦ</span>, «levaram seu espírito faccioso a tamanho grau de furor», 1Cl 45:7. — DELG, s.v. <span class=\"greek\">ἔρις</span>.</p></section></article>\n<article id=\"entry-exerchomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξέρχομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exérchomai⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξέρχομαι</span>: futuro <span class=\"greek\">ἐξελεύσομαι</span> (esta forma de futuro também em M. Ant. 10, 36); segundo aoristo <span class=\"greek\">ἐξῆλθον</span> (mas <span class=\"greek\">ἐξῆλθα</span> [como, p. ex., 2 Km 11:23] em <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:3</a> D; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:40</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:17</a> [Is 52:11]; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2:19</a>; 3Jo 7, variante de leitura; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 18:4</a>. — Para <span class=\"greek\">ἐξήλθοσαν</span>, ver Js 8:19; 1Cr 2, 53; Jdth 10:6; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:11</a> D; cf. o escólio a Lycophron, v. 252, <span class=\"greek\">ἤλθοσαν</span>); perfeito <span class=\"greek\">ἐξελήλυθα</span> (ver <span class=\"greek\">ἔρχομαι</span>; Hom. e outros; inscrições, papiros, LXX, pseudepígrafos; Jos., Bell. 2, 480; Just.; Ar. [JTS 25, 1924, 76, linha 41]).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Deslocar-se para fora de uma área ou afastar-se dela.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> De entidades animadas: sair, vir para fora, ir embora, retirar-se.</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. De seres humanos.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">א</span>. Frequentemente com indicação do lugar de procedência, mencionando-se ou não o destino. <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span> (Hdt. 8, 75, 1; 9, 12); <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μνημείων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:28</a>; 27:53; <span class=\"greek\">ἐκ</span> <span class=\"greek\">γῆς</span> <span class=\"greek\">Χαλδαίων</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">At 7:4</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.7.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 7:31</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.30\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:30</a> (<span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεως</span>, como em X., Hell. 6, 5, 16); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.22.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 22:18</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:16</a>; 1Cl 10:2. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πλοίου</span>, «sair do barco», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:2</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.15\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:15</a>, 17s. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σταδίου</span>, AcPl Ha 5, 14 (Just., A I, 45, 5 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἰ</span>.). — <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (Ps.-Heraclitus, Ep. 5, 3 [=Malherbe, p. 196]; Aesop, Fab. 141 P. [248b H.; 202 Ch.; 146a H-H.]; POxy 472, 1; 528, 7; LXX; JosAs 23:16 <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">αὐτου</span>; Jos., Ant. 12, 407 <span class=\"greek\">ἀ</span>. <span class=\"greek\">τ</span>. <span class=\"greek\">Ἱερος</span>.; Just., A I, 60, 2 <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Αἰγύπτου</span>, D. 91, 3 e outros), <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Βηθανίας</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.11.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 11:12</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 17:29</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.4.15\" target=\"_blank\" rel=\"noopener noreferrer\">Fp 4:15</a>; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">πόλεως</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:5</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:1</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.40\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:40</a>; <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἐμοῦ</span>, «afasta-te de mim», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.8\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 5:8</a>; <span class=\"greek\">ἐξ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀνδρός</span>, «deixar o marido», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:12</a> D. — <span class=\"greek\">ἔξω</span> <span class=\"greek\">τινός</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:14</a> (cf. Jdth 14:2); seguido de <span class=\"greek\">εἰς</span> com acusativo de lugar, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:17</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.68\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:68</a>; seguido de <span class=\"greek\">παρά</span> com acusativo de lugar, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.13\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:13</a>; seguido de <span class=\"greek\">πρός</span> com acusativo de pessoa, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:13</a>. — Somente com <span class=\"greek\">εἰς</span>, <span class=\"greek\">ἐξελεύσονται</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">σκότος</span>, «terão de sair para as trevas», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:12</a>, variante de leitura. — Somente com genitivo (Hom. e outros; Longus 4, 23, 2; POxy 942, 4), <span class=\"greek\">τ</span>. <span class=\"greek\">οἱκίας</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:1</a> (variantes <span class=\"greek\">ἐκ</span> e <span class=\"greek\">ἀπό</span>). — <span class=\"greek\">ἐκεῖθεν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:21</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:1</a>, 10; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:4</a>; 11:53; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.43\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 4:43</a>; <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ἐξέλθῃς</span> <span class=\"greek\">ἐκεῖθεν</span>, «jamais serás solto dali», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:26</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.59\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 12:59</a>; D 1:5; <span class=\"greek\">ὅθεν</span> <span class=\"greek\">ἐξῆλθον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.44\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:44</a>; Lc 11:24b. — <span class=\"greek\">εἰσέρχεσθαι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἐ</span>., <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 1:21</a>. — Cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:24</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ב</span>. Às vezes, o lugar de procedência não é nomeado expressamente, mas pode ser inferido do contexto: sair de uma região ou casa, sair (de), desembarcar de um navio etc.; Mt 9:31s; 12:14; 14:14; 18:28; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.35\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:35</a>, 45; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.42\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:42</a>; 5:27; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.9\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:9</a>; 11:31, 44; 13:30s; 18:1, 4; At 12:9s, 17; 16:3 («sair»); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:8</a>; D 11:6; AcPl Ha 3, 26; 7, 36; AcPl Ant 13, 2 (=Aa I 236, 6). <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἔξω</span> (cf. Gn 39:12ss), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.75\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:75</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.62\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 22:62</a>; Jo 19:4s; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 3:12</a>. Semelhantemente, deixar um lugar e fazer-se presente em outro: «aparecer» (Aristoph., Av. 512, Ach. 240), <span class=\"greek\">ἐξῆλθον</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">Φ</span>., «os fariseus apareceram», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.8.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 8:11</a> (assim LKoehler, TZ 3, 1947, 471; também KSchmidt e ADebrunner, ibid. 471–73).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ג</span>. Com indicação do destino: «(levantar-se e) sair», «preparar-se» — de um servo, para cumprir uma missão (Mitt-Wilck. II/2, 89, 36); <span class=\"greek\">οἱ</span> <span class=\"greek\">ἄγγελοι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:49</a>. Frequentemente com <span class=\"greek\">εἴς</span> <span class=\"greek\">τι</span> (X., Hell. 7, 4, 24 e outros): <span class=\"greek\">εἰς</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">ὁδούς</span>, «para as ruas», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.22.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 22:10</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πυλῶνα</span>, 26:71; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.68\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:68</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἔρημον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:7</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ὄρος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἐλαιῶν</span>, «para o monte das Oliveiras», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:30</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:26</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Γαλιλαίαν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.43\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:43</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">Μακεδονίαν</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.10\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:10</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.2.13\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 2:13</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">λεγόμενον</span> <span class=\"greek\">κρανίου</span> <span class=\"greek\">τόπον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.17\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:17</a>; <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.4.1\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 4:1</a>; 2Jo 7 (Just., A I, 39, 3; cf. D 53, 3 <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">οἰκουμένην</span>). <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑπάντησίν</span> <span class=\"greek\">τινι</span>, «ao encontro de alguém» (Jdth 2:6, variante com genitivo; cf. <span class=\"greek\">ἐ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπάντησίν</span> <span class=\"greek\">τινι</span>, 1 Esdr 1:23; 1 Macc 12:41; TestJob 9:7; ou <span class=\"greek\">εἰς</span> <span class=\"greek\">συνάντησίν</span> <span class=\"greek\">τινι</span>, Tob 11:16 BA; Jdth 2:6; 1 Macc 3:11, 16; 10:2, 86; JosAs 5:3 [códice B]; 25:8), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.34\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:34</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.12.13\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 12:13</a>; também <span class=\"greek\">εἰς</span> <span class=\"greek\">ὑπάντησίν</span> <span class=\"greek\">τινος</span> (cf. <span class=\"greek\">εἰς</span> <span class=\"greek\">ἀπάντησίν</span> <span class=\"greek\">τινος</span>, 2Cr 19:2; Tob 11:16 S; 1 Macc 12:41, variante [ed. WKappler 1936]; <span class=\"greek\">εἰς</span> <span class=\"greek\">συνάντησίν</span> <span class=\"greek\">τινος</span>, 3:11, variante [ed. Kappler]), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:1</a> (EPeterson, ZST 7, 1930, 682–702); também <span class=\"greek\">ἀπάντησιν</span> <span class=\"greek\">αὐτου</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.25.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 25:6</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.15\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:15</a>, variante. <span class=\"greek\">πρός</span> <span class=\"greek\">τινα</span> (cf. 1 Macc 9:29; Tob 11:10 BA), «a alguém», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.18.29\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 18:29</a>, 38; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.8.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 8:17</a>. <span class=\"greek\">ἐπί</span> <span class=\"greek\">τινα</span>, «sair contra alguém» (PTebt 283, 9 [séc. I a.C.] <span class=\"greek\">ἐξελήλυθεν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">μητέρα</span> <span class=\"greek\">μου</span>; Jdth 2:7), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.55\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:55</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.14.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 14:48</a>; <span class=\"greek\">ἐπί</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆν</span>, «pisar em terra», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:27</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ד</span>. Com finalidade expressa pelo infinitivo: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:8</a>; 20:1; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.21\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:21</a>; 4:3; Lc 7:25s; 8:35; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 20:1</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 20:8</a>; GJs 11:1; 18:1; com genitivo do infinitivo, <span class=\"greek\">τοῦ</span> <span class=\"greek\">σπείρειν</span>, «para semear», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:3</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.8.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 8:5</a>; pelo particípio, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:2</a>; 1Cl 42:3; com <span class=\"greek\">ἵνα</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 6:2</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. De seres transcendentes.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">א</span>. No uso joanino, a respeito de Jesus, que procede do Pai: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐξῆλθον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.8.42\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 8:42</a>; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πρὸς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">θεὸν</span> <span class=\"greek\">ὑπάγει</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.3\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 13:3</a>; <span class=\"greek\">παρὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐξῆλθον</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.27\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:27</a>; cf. 17:8 (quanto a <span class=\"greek\">ἐξ</span>. <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span>, cf. Nm 16:35); <span class=\"greek\">ἐξῆλθον</span> <span class=\"greek\">παρὰ</span> (variante <span class=\"greek\">ἐκ</span>) <span class=\"greek\">τοῦ</span> <span class=\"greek\">πατρός</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.16.28\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 16:28</a>; <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐξῆλθες</span>, v. 30.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ב</span>. De espíritos que saem ou se retiram das pessoas (Damasc., Vi. Isid. 56 <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐπείθετο</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">δαιμόνιον</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">γυναικὸς</span> <span class=\"greek\">ἐξελθεῖν</span>; PGM 4, 1243s <span class=\"greek\">ἔξελθε</span>, <span class=\"greek\">δαῖμον</span>, … <span class=\"greek\">καὶ</span> <span class=\"greek\">ἀπόστηθι</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δεῖνα</span>). <span class=\"greek\">ἔκ</span> <span class=\"greek\">τινος</span>, Mc 1:25s; 5:8; 7:29; 9:25; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:35</a>, duas vezes como variante de leitura; <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> (cf. En 22:7 <span class=\"greek\">τὸ</span> <span class=\"greek\">πνεῦμα</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐξελθὸν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">Ἄβελ</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:43</a>; 17:18; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:35</a> duas vezes, 41; 8:29, 33, 35, 38; 11:24; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:18</a>. Uso absoluto: <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:13</a>; 7:30; 9:26, 29; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.36\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:36</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:7</a> (texto provavelmente danificado ou talvez anacoluto).</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. De animal: «sair», a respeito de uma serpente, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.3\" target=\"_blank\" rel=\"noopener noreferrer\">At 28:3</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> De entidades inanimadas: sair.</p>\n<p class=\"entry-text\"><span class=\"greek\">α</span>. De líquido: sair, fluir (Jz 15:19; ViIs, ViEzk, ViHab, ViJer e outros, 3 [p. 69, 7 Sch.]); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.34\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 19:34</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.14.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 14:20</a>; AcPl Ha 11, 2 (ver <span class=\"greek\">γάλα</span> a).</p>\n<p class=\"entry-text\"><span class=\"greek\">β</span>. De ruído, mensagem etc.: «ressoar uma voz», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.16.17\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 16:17</a>; 19:5 (SyrBar 13:1). O som da proclamação se espalha (cf. Mq 4:2), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rm 10:18</a> (Sl 18:5); também notícias e relatos, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:26</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.14\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 4:14</a>; 7:17; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 1:28</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:23</a>; <span class=\"greek\">ἡ</span> <span class=\"greek\">πίστις</span> <span class=\"greek\">τινός</span>, «a notícia da fé de alguém», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1:8</a>; cf. B 11:8; 19:4. Um decreto é promulgado (Dn 2:13, Teodócio), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 2:1</a>. <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span> <span class=\"greek\">ἐξῆλθεν</span>; «porventura a palavra de Deus (a proclamação cristã) teve origem em vós?», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.14.36\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 14:36</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">γ</span>. Com indicação da fonte ou lugar de procedência: do relâmpago, <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">ἀνατολῶν</span>, «parte do oriente», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.27\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:27</a>. Das palavras: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">στόματος</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">εὐλογία</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">κατάρα</span>, «da mesma boca procedem bênção e maldição», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Tg 3:10</a>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">καρδίας</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">διαλογισμοὶ</span> <span class=\"greek\">πονηροί</span>, «do coração procedem maus pensamentos», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.15.19\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 15:19</a>; cf. v. 18. De uma espada: <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">στόματος</span>, «saiu da boca», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 19:21</a>.</p>\n<p class=\"entry-text\"><span class=\"greek\">δ</span>. Do tempo ou de uma condição: acabar, desaparecer (Hippocr., de doenças; X., An. 7, 5, 4, do tempo; Gn 47:18). <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐλπὶς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἐργασίας</span> <span class=\"greek\">αὐτῶν</span>, «desaparecera a esperança de lucro deles», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:19</a>; cf. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 5:30</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Partir pela morte, morrer: <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span>, «deixar o mundo», eufemismo para «morrer» (assim na expressão judaica אֲזַל מִן עָלְמָא, Targ. Koh. 1:8; TestAbr A 1 p. 78, 8: Stone p. 4 [<span class=\"greek\">τὸν</span> <span class=\"greek\">κόσμον</span> B 4 p. 109, 6: Stone p. 66]; ParJer 4:10; ver Dalman, Worte 141; ver também HKoch, ZNW 21, 1922, 137s. — Os gregos dizem <span class=\"greek\">ἐξέρχ</span>. <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>: Iambl., Myst. em Stob. 1, 49, 67, p. 457, 9; Sallust. 19, 2, p. 34, 20; também TestAbr B 7 p. 112, 7 [Stone p. 72] e ParJer 6:20 <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">σώματος</span>; ou <span class=\"greek\">τοῦ</span> <span class=\"greek\">βίου</span>: Himerius, Or. [Ecl.] 2, 14; TestAbr B 1 p. 105, 4 [Stone p. 58]; absolutamente, Ar. [Milne, 76, 41]), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 5:10</a>; 2Cl 5:1; 8:3; AcPl Ha 6, 32. Também <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">κ</span>., ApcPt 2:5.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">③</span> Proceder por descendência, sair, provir: <span class=\"greek\">ἐκ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">ὀσφύος</span> <span class=\"greek\">τινός</span>, «dos lombos de alguém», isto é, «ser descendente dele» (Gn 35:11; 2Cr 6:9), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.5\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:5</a>. Com genitivo de origem, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:6</a> (Mq 5:1).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">④</span> Interromper uma associação, retirar-se: <span class=\"greek\">ἐξέλθατε</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">μέσου</span> <span class=\"greek\">αὐτῶν</span>, «saí do meio deles», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.6.17\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 6:17</a> (Is 52:11). Deixar uma congregação, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1JN.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">1Jo 2:19</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">⑤</span> Livrar-se de uma situação difícil, escapar: <span class=\"greek\">ἐξῆλθεν</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">χειρὸς</span> <span class=\"greek\">αὐτῶν</span>, «escapou das mãos deles», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.10.39\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 10:39</a>. — M-M. EDNT. TW.</p></section></article>\n<article id=\"entry-exestakenai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξεστακέναι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exestakénai⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξεστακέναι</span>: ver <span class=\"greek\">ἐξίστημι</span>.</p></section></article>\n<article id=\"entry-exestin-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἔξεστιν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦éxestin⟧</span><span class=\"separator\">·</span><span>verbo impessoal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἔξεστιν</span>: verbo impessoal, terceira pessoa do singular de <span class=\"greek\">ἔξειμι</span>, não empregado como tal; futuro <span class=\"greek\">ἐξέσται</span> na LXX (Eur., Hdt. e outros; LXX; ParJer 5:20; Just., A I, 66, 1; Ath.).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Estar autorizado a fazer alguma coisa; ser correto, autorizado, permitido, apropriado.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Seguido de infinitivo presente (Lucian, Jud. 3; Esth 8:12g; 4 Macc 1:12; Ath. 32, 2 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:2</a>, 12; 14:4. Seguido de infinitivo aoristo (X., An. 4, 3, 10; Ath. 6:3 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:10</a>; 15:26 D; 19:3; 22:17; 27:6; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 3:4</a> (<span class=\"greek\">ἔξεστιν</span> … <span class=\"greek\">ἤ</span>); 12:14; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:9</a>; 14:3. Sem infinitivo, facilmente suprido pelo contexto (cf. PRyl 77, 43 <span class=\"greek\">τοῦτο</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἐξῆν</span>; Ath. 16, 3), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:24</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.8.36\" target=\"_blank\" rel=\"noopener noreferrer\">At 8:36</a> [37], variante; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 10:23</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Seguido de dativo de pessoa e infinitivo presente (X., Hiero 1, 26; BGU 1127, 20 [18 a.C.]; PSI 203, 7; Jos., Ant. 13, 252), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.6.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 6:18</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.16.21\" target=\"_blank\" rel=\"noopener noreferrer\">At 16:21</a>; 22:25; GJs 2:2. Seguido de dativo de pessoa e infinitivo aoristo (2 Esdr 4:14; 1 Macc 14:44), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:15</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.10.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 10:2</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.5.10\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 5:10</a>; 18:31 (JAllen, Why Pilate?: CMoule Festschr., 1970, 78–83; sobre as questões jurídicas, ver também SSafrai, CRINT I/1, 397–400); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.37\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:37</a>; GJs 1:2; 2:2. — Seguido de dativo de pessoa sem necessidade de suprir infinitivo (PRyl 62, 16 <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">ἄλλα</span> <span class=\"greek\">ἔξεστί</span> <span class=\"greek\">μοι</span>), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.6.12\" target=\"_blank\" rel=\"noopener noreferrer\">1Co 6:12</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓒ</span> Seguido de acusativo com infinitivo (Pla., Pol. 290d e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 2:26</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 6:4</a> (ver B-D-F §409, 3; Rob. 1084s); 20:22.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓓ</span> O particípio de <span class=\"greek\">ἔξεστιν</span> é <span class=\"greek\">ἐξόν</span>; pela adição da cópula, frequentemente subentendida (como em Isaeus 6, 50; Jos., Ant. 8, 404), passa a significar o mesmo que <span class=\"greek\">ἔξεστιν</span>: seguido de infinitivo presente, ISm 8:2; seguido de dativo de pessoa e infinitivo aoristo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">2Co 12:4</a>; PEg2 48 (cf. Just., A I, 66, 1). <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἦν</span> com dativo e infinitivo aoristo (Esth 4:2; Jos., Ant. 20, 202), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.12.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 12:4</a>. Com dativo e infinitivo subentendido, <span class=\"greek\">μὴ</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἐ</span>. <span class=\"greek\">αὖτῷ</span>, «ele não tinha autoridade», MPol 12:2.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Estar dentro dos limites da possibilidade; ser possível. O particípio de <span class=\"greek\">ἐ</span>. (ver acima), seguido de infinitivo aoristo, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.29\" target=\"_blank\" rel=\"noopener noreferrer\">At 2:29</a>. — B. 647. M-M. TW.</p></section></article>\n<article id=\"entry-exetazo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξετάζω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exetázō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξετάζω</span>: futuro <span class=\"greek\">ἐξετάσω</span> na LXX; primeiro aoristo <span class=\"greek\">ἐξήτασα</span>; perfeito, primeira pessoa do plural <span class=\"greek\">ἐξητάκαμεν</span> (Ath. 23, 1). Passivo: aoristo, terceira pessoa do singular <span class=\"greek\">ἐξητάσθη</span> (Just., A II, 2, 12); particípio perfeito <span class=\"greek\">ἐξητασμένος</span> (Ath., R. 64, 6 e outros) (<span class=\"greek\">ἐτάζω</span>, «examinar, pôr à prova»; ver também o próximo verbete; desde Theognis 1, 1016; Soph., Thu. e outros, também inscrições, papiros, LXX, pseudepígrafos, Philo, Joseph., Just., Tat., Ath.).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Procurar descobrir mediante métodos cuidadosos, que podem incluir investigação pessoal: escrutinar, examinar, investigar, inquirir (Thu. e outros; Wsd 6:3; Sir 3:21; Just., A I, 7, 2 e outros; Tat. 30, 2; Ath. 24, 1 e outros). <span class=\"greek\">ἀκριβῶς</span> <span class=\"greek\">ἐ</span>. (Lucian, Dial. Mort. 30, 3; POxy 237 VI, 31 <span class=\"greek\">τὸ</span> <span class=\"greek\">πρᾶγμα</span> <span class=\"greek\">ἀκρειβῶς</span> <span class=\"greek\">ἐξητασμένον</span>; Dt 19:18; TestJob; Philo, Somn. 1, 228; Jos., Ant. 3, 70; Just., A I, 32, 2); <span class=\"greek\">τὶ</span>, «alguma coisa» (Dionys. Hal., Ep. ad Pomp. 1, 16 <span class=\"greek\">τὴν</span> <span class=\"greek\">ἀλήθειαν</span>; Dio Chrys. 17 [34], 26; Philo, Migr. Abr. 185; Just., D. 112, 1 <span class=\"greek\">τὴν</span> <span class=\"greek\">δύναμιν</span> … <span class=\"greek\">τῶν</span> <span class=\"greek\">εἰρημένων</span>), Hs 9, 13, 6; <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, «fazer uma busca cuidadosa por alguém», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:8</a> (quanto a <span class=\"greek\">ἐ</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span>, cf. Pla., Leg. 3, 685a; PGen 54, 30; BGU 380, 5; Jos., C. Ap. 2, 237; Just., D. 1, 3 <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">θείου</span>). Seguido de pergunta indireta (cf. Thu. 7, 33, 6; Epicrates Com. [séc. IV a.C.] 11, 17, vol. II p. 287 Kock; Aelian, VH 1, 28; Just., A I, 14, 4 e outros), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:11</a>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Inquirir intensamente, interrogar, examinar; <span class=\"greek\">τινά</span>, «alguém» (Soph., Oed. Col. 211; X., Mem. 1, 2, 36; BGU 372 II 13; PGrenf I 53, 22; Just., D. 92, 2 e outros).</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> Em sentido geral, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.21.12\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 21:12</a>; Ox 654, 32 [<span class=\"greek\">ἐξ</span>]<span class=\"greek\">ετάζουσιν</span> = ASyn. 60, 7 (seguido de pergunta direta; de outro modo, <span class=\"greek\">ἐρωτάω</span> e <span class=\"greek\">ἐπερωτάω</span>; ver M-EBoismard, RB 54, 1947, 491). <span class=\"greek\">περὶ</span> <span class=\"greek\">τοιούτων</span> <span class=\"greek\">πραγμάτων</span> <span class=\"greek\">ἐξεταζόμενος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">σωτήρ</span>, «quando o Salvador foi interrogado acerca de tais assuntos», GMary 463, 12.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> Como termo técnico jurídico: interrogar judicialmente, especialmente em ligação com tortura (Polyb. 15, 27, 7; Herodian 4, 5, 3; 4; SIG 780, 11 [6 a.C.]; Dt 19:18; Esth 1:1o; Sir 23:10; Jos., Ant. 18, 183; Just., A I, 39, 3); na voz passiva, Hs 9, 28, 4; seguido de oração relativa, <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">ἔπραξε</span>, D 1:5 (cf. PGM 7, 331 <span class=\"greek\">περὶ</span> <span class=\"greek\">ὧν</span> <span class=\"greek\">σε</span> <span class=\"greek\">ἐξετάζω</span>). — DELG, s.v. <span class=\"greek\">ἐτάζω</span>. M-M.</p></section></article>\n<article id=\"entry-exetasmos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξετασμός, οῦ, ὁ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exetasmós⟧</span><span class=\"separator\">·</span><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξετασμός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (ver verbete anterior; Demosth. 18, 16; Diod S 11, 3, 7; 9; Plut., Mor. 1068b; IG II², 500, 12; LXX): investigação sistemática dos fatos, exame, inquérito. Do julgamento de Deus (Wsd 4:6), <span class=\"greek\">ἐ</span>. <span class=\"greek\">ἀσεβεῖς</span> <span class=\"greek\">ὀλεῖ</span>, «uma investigação rigorosa destruirá os ímpios», 1Cl 57:7 (Pv 1:32).</p></section></article>\n<article id=\"entry-exetastikos-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξεταστικῶς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exetastikôs⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξεταστικῶς</span>, advérbio (ver <span class=\"greek\">ἐξετάζω</span>; Demosth. 17, 13): mediante investigação minuciosa, PEg2 43–44 (conforme restauração editorial <span class=\"greek\">ἐξ̣</span>[<span class=\"greek\">ετας</span>]<span class=\"greek\">τικῶς</span>).</p></section></article>\n<article id=\"entry-exephnes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξέφνης</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exéphnēs⟧</span><span class=\"separator\">·</span><span>advérbio; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξέφνης</span>: ver <span class=\"greek\">ἐξαίφνης</span>.</p></section></article>\n<article id=\"entry-exechythen-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξεχύθην</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exechýthēn⟧</span><span class=\"separator\">·</span><span>forma verbal; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξεχύθην</span>: ver <span class=\"greek\">ἐκχέω</span>.</p></section></article>\n<article id=\"entry-execho-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξέχω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exéchō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξέχω</span> (ver <span class=\"greek\">ἔχω</span>; Aristoph. e outros; SIG 827 III, 11 [116/117 d.C.]; LXX; ViDa 1 [p. 76, 13 Sch.]; cf. 2 Esdr 13:25, 27 <span class=\"greek\">ὁ</span> <span class=\"greek\">πύργος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐξέχων</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">οἴκου</span> <span class=\"greek\">τ</span>. <span class=\"greek\">βασιλέως</span>; Just., D. 91, 2): ser prontamente perceptível, destacar-se, sobressair, ser proeminente. De lugares elevados como posições de honra: <span class=\"greek\">οἱ</span> <span class=\"greek\">ἐξέχοντες</span> <span class=\"greek\">τόποι</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.20.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 20:28</a>, variante de leitura = ASyn. 216, 38 [Agr 22].</p></section></article>\n<article id=\"entry-exegeomai-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξηγέομαι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exēgéomai⟧</span><span class=\"separator\">·</span><span>verbo médio depoente</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξηγέομαι</span> (ver verbete seguinte): médio depoente, futuro, terceira pessoa do plural <span class=\"greek\">ἐξηγήσονται</span>, Jó 12:8; primeiro aoristo <span class=\"greek\">ἐξηγησάμην</span>. Passivo: aoristo, terceira pessoa do singular <span class=\"greek\">ἐξηγήθη</span> (Just., D. 68, 6); infinitivo <span class=\"greek\">ἐξήγηθῆναι</span> (Just., D. 55, 3); particípio perfeito <span class=\"greek\">ἐξηγημένα</span> (Just., D. 79, 1; 126, 5) (Hom. e outros). O significado primordial é «conduzir» (ver <span class=\"greek\">ἡγέομαι</span> 1), mas nunca ocorre com esse valor na literatura aqui considerada.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Relatar pormenorizadamente, contar, narrar, descrever, sobretudo em narrativa (assim Hdt.; inscrições, papiros, LXX, EpArist; Philo, Leg. All. 3, 21; Berosus: 680 Fgm. 8a 140 Jac. [em Jos., C. Ap. 1, 140]; Just., D. 58, 4; mas em 112, 1 «interpretar», e em 68, 7 «traduzir»). <span class=\"greek\">τὶ</span>, «alguma coisa»; <span class=\"greek\">τὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ὁδῷ</span>, «as experiências deles durante o caminho», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.35\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:35</a>; <span class=\"greek\">πάντα</span>, GPt 11:45; <span class=\"greek\">τ</span>. <span class=\"greek\">δεσμὸν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ἀγάπης</span> <span class=\"greek\">τ</span>. <span class=\"greek\">θεοῦ</span>, «descrever o vínculo do amor de Deus», 1Cl 49:2. <span class=\"greek\">τί</span> <span class=\"greek\">τινι</span>, «relatar algo a alguém» (Jz 7:13), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.8\" target=\"_blank\" rel=\"noopener noreferrer\">At 10:8</a>; Hv 4, 2, 5; GJs 19:3. <span class=\"greek\">καθ</span>’ <span class=\"greek\">ἓν</span> <span class=\"greek\">ἕκαστον</span>, «um por um», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.19\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:19</a>. <span class=\"greek\">ἐ</span>. <span class=\"greek\">καθὼς</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεὸς</span> <span class=\"greek\">ἐπεσκέψατο</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.15.14\" target=\"_blank\" rel=\"noopener noreferrer\">At 15:14</a>; <span class=\"greek\">ὅσα</span> <span class=\"greek\">ἐποίησεν</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>, v. 12; <span class=\"greek\">ἐξηγουμένου</span> <span class=\"greek\">Παύλου</span> <span class=\"greek\">ἃ</span> <span class=\"greek\">πέπονθεν</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">Φιλίπποις</span>, AcPl Ha 6, 4.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Expor em grandes pormenores, explicar. Frequentemente, termo técnico da atividade de sacerdotes e adivinhos que transmitem informações ou revelam segredos divinos; também empregado acerca dos próprios seres divinos (Pla., Trag., Thu., X.; Wetstein sobre <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:18</a>. — Arrian, Anab. 2, 3, 3, acerca de adivinhos: <span class=\"greek\">τὰ</span> <span class=\"greek\">θεῖα</span> <span class=\"greek\">ἐξηγεῖσθαι</span>; 6, 2, 3; Ael. Aristid. 13 p. 219 D.: <span class=\"greek\">τὰ</span> <span class=\"greek\">μέλλοντα</span> <span class=\"greek\">ὥσπερ</span> <span class=\"greek\">μάντις</span> <span class=\"greek\">ἐξηγεῖτο</span>; 45, 30 K., acerca da proclamação dos milagres de Serápis; Pollux 8, 124 <span class=\"greek\">ἐξηγηταὶ</span> <span class=\"greek\">δ</span>’ <span class=\"greek\">ἐκαλοῦντο</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">διοσημιῶν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">ἄλλων</span> <span class=\"greek\">ἱερῶν</span> <span class=\"greek\">διδάσκοντες</span>, isto é, «chamam-se intérpretes/expositores aqueles que ensinam a respeito dos presságios e de outras coisas sagradas»; Jos., acerca da interpretação da Lei: Bell. 1, 649; 2, 162; Ant. 18, 81; Lucian, Peregr. 11 <span class=\"greek\">τῶν</span> <span class=\"greek\">βίβλων</span> <span class=\"greek\">τὰς</span> <span class=\"greek\">μὲν</span> <span class=\"greek\">ἐξηγεῖτο</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">διεσάφει</span>). <span class=\"greek\">ἐκεῖνος</span> <span class=\"greek\">ἐξηγήσατο</span>, «ele deu a conhecer ou transmitiu notícia de [Deus invisível]», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.1.18\" target=\"_blank\" rel=\"noopener noreferrer\">Jo 1:18</a> (assim também JMichael, JTS 22, 1921, 14–16, contra RHarris, The Origin of the Prologue 1917, 35; ver Hdb.³ ad loc.; APersson, D. Exegeten u. Delphi 1918). — B. 1238. M-M. TW. Spicq.</p></section></article>\n<article id=\"entry-exegesis-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξήγησις, εως, ἡ</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exḗgēsis⟧</span><span class=\"separator\">·</span><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξήγησις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span>.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">①</span> Narração que apresenta descrição pormenorizada: narrativa, descrição (ver verbete anterior; Thu. e outros; Pla., Leg. 1, 631a; Polyb. 6, 3, 1; Jz 7:15 B; Sir 21:16; Just., A I, 68, 3 e outros; Tat. 35, 2). <span class=\"greek\">τῆς</span> <span class=\"greek\">τελειότητος</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔστιν</span> <span class=\"greek\">ἐ</span>., «sua perfeição não pode ser plenamente descrita», 1Cl 50:1. <span class=\"greek\">κατὰ</span> <span class=\"greek\">πᾶσαν</span> <span class=\"greek\">ἐ</span>., «em todo relato», AcPl Ha 6, 13.</p>\n<p class=\"entry-text\"><span class=\"sense-number\">②</span> Exposição pormenorizada de alguma coisa: explicação, interpretação (Pla. e outros; Diod S 2, 29, 3; Dionys. Hal., De Thu. Jud. 54, 3; Philo, Vi. Cont. 78; Jos., Ant. 11, 192; Just., D. 79, 2; 115, 2 e outros, «exposição»; 124, 3 e outros, «tradução»); <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span>, Hv 3, 7, 4. Segundo Eusébio, a obra de Papias intitulava-se <span class=\"greek\">λογίων</span> <span class=\"greek\">κυριακῶν</span> <span class=\"greek\">ἐξήγησις</span> (Papias 2:1); segundo Apolinário, <span class=\"greek\">ἐ</span>. <span class=\"greek\">τῶν</span> <span class=\"greek\">κυριακῶν</span> <span class=\"greek\">λόγων</span> (3:1); ver também 3:8, 9; ver <span class=\"greek\">κυριακός</span>. — TW. Sv.</p></section></article>\n<article id=\"entry-exiein-exeesan-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξῄειν, ἐξήεσαν</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exḗiein, exḗesan⟧</span><span class=\"separator\">·</span><span>formas verbais; remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξῄειν</span>, <span class=\"greek\">ἐξήεσαν</span>: imperfeito de <span class=\"greek\">ἔξειμι</span>.</p></section></article>\n<article id=\"entry-hexekonta-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑξήκοντα</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hexḗkonta⟧</span><span class=\"separator\">·</span><span>numeral indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἑξήκοντα</span>, indeclinável (Hom. e outros; papiros, LXX, pseudepígrafos, Philo; Jos., Ant. 11, 18): sessenta. <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:8</a>, 23; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.4.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mc 4:8</a>, 20; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.24.13\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 24:13</a> (Strabo 16, 2, 36: sessenta estádios de Jerusalém; Jos., Vi. 115 <span class=\"greek\">ἀπέχειν</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">σταδίους</span>); <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.5.9\" target=\"_blank\" rel=\"noopener noreferrer\">1Tm 5:9</a>; <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ap 11:3</a>; 12:6; 13:18. — DELG, s.v. <span class=\"greek\">ἕξ</span>. M-M.</p></section></article>\n<article id=\"entry-hexes-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἑξῆς</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦hexês⟧</span><span class=\"separator\">·</span><span>advérbio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἑξῆς</span>, advérbio (Hom. e posteriores): seguinte numa série, no lugar seguinte (Dionys. Hal. 1, 71, 2; Philo, Op. M. 131 e outros; Just., D. 42, 2 e outros, em citações e certas linhas argumentativas), Dg 3:1. Em relação ao tempo — como sempre no NT —, <span class=\"greek\">τῇ</span> <span class=\"greek\">ἑ</span>. <span class=\"greek\">ἡμέρᾳ</span> (SIG 1170, 24; SIG² 680, 4; Jos., Ant. 4, 302), «no dia seguinte», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 9:37</a>. Frequentemente o substantivo deve ser suprido: <span class=\"greek\">τῇ</span> <span class=\"greek\">ἑξῆς</span> (EpArist 262; Jos., Bell. 2, 430; POxy 1063, 6), <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.1\" target=\"_blank\" rel=\"noopener noreferrer\">At 21:1</a>; 25:17; 27:18. Com <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">ἑξῆς</span>, <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.11\" target=\"_blank\" rel=\"noopener noreferrer\">Lc 7:11</a>, deve-se suprir <span class=\"greek\">χρόνῳ</span>: «(pouco) depois». — DELG. M-M.</p></section></article>\n<article id=\"entry-execheo-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξηχέω</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exēchéō⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξηχέω</span> (ver <span class=\"greek\">ἠχέω</span>): futuro, terceira pessoa do singular <span class=\"greek\">ἐξηχήσει</span>, Sir 40:13; aoristo, terceira pessoa do plural <span class=\"greek\">ἐξήχησαν</span>, Jr 3:14; perfeito passivo <span class=\"greek\">ἐξήχημαι</span> (normalmente ativo intransitivo, «soar, ressoar»: Jl 3:14; Sir 40:13; Philo, In Flacc. 39; Rer. Div. Her. 15; Dec. 46); transitivo, «fazer ressoar ou ser ouvido» (Polyb. 30, 4, 7; Philo, Abr. 180); passivo, «ser levado a ressoar, repercutir» (3 Macc 3:2). <span class=\"greek\">ἀφ</span>’ <span class=\"greek\">ὑμῶν</span> <span class=\"greek\">ἐξήχηται</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">λόγος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span>, «a palavra do Senhor repercutiu a partir de vós», <a class=\"reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1Ts 1:8</a>. — DELG, s.v. <span class=\"greek\">ἠχή</span>.</p></section></article>\n<article id=\"entry-exiemi-bdag\" class=\"entry-card\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">ἐξίημι</h1><div class=\"entry-meta\"><span class=\"transliteration\">⟦exíēmi⟧</span><span class=\"separator\">·</span><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução literal</div><p class=\"entry-text\"><span class=\"greek\">ἐξίημι</span> (ver <span class=\"greek\">ἵημι</span>): infinitivo aoristo <span class=\"greek\">ἐξείναι</span>; abrir caminho para que alguém chegue a um destino, permitir que alguém saia, enviar para fora. <span class=\"greek\">ἐξεῖναι</span> <span class=\"greek\">Παῦλον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ῥώμην</span>, «enviar Paulo a Roma», AcPl Ha 6, 15s.</p></section></article>"};
